package com.learnspherex.security;
import java.util.*; import javax.crypto.SecretKey; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import com.learnspherex.auth.RoleName;
@Service public class JwtService { private final SecretKey key; private final long expiry; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long e){key=Keys.hmacShaKeyFor(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8));expiry=e;} public String generateToken(String username,Set<RoleName> roles){return Jwts.builder().subject(username).claim("roles",roles.stream().map(Enum::name).toList()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiry)).signWith(key).compact();} public String username(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token,UserDetails user){try{return username(token).equals(user.getUsername())&&Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getExpiration().after(new Date());}catch(JwtException|IllegalArgumentException e){return false;}} }
